WITH exploded AS (SELECT id, plan, effective_from, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) li AS tier_value) SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, CASE WHEN tier_value >= 68 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, PERCENTILE_APPROX(tier_value, ARRAY(0.25, 0.5, 0.75)) AS tier_value_quartiles, COUNT(*) FILTER (WHERE plan = 'starter') AS starter_rows, ROUND(AVG(tier_value), 2) AS avg_tier_value FROM exploded GROUP BY quarter_start, tier_value_tier
